package com.kpriet.studentportal;
import javax.servlet.*;import javax.servlet.http.*;import java.io.*;import java.sql.*;
public class FileServlet extends HttpServlet { protected void doGet(HttpServletRequest req,HttpServletResponse res)throws IOException{if(req.getSession().getAttribute("loggedIn")==null){res.sendError(403);return;}int id=Integer.parseInt(req.getParameter("id"));try(Connection c=DB.get();PreparedStatement ps=c.prepareStatement("SELECT file_path,file_type,original_name FROM student_files WHERE id=?")){ps.setInt(1,id);ResultSet rs=ps.executeQuery();if(!rs.next()){res.sendError(404);return;}File f=new File(getServletContext().getRealPath("/")+rs.getString("file_path"));if(!f.exists()){res.sendError(404);return;}res.setContentType(rs.getString("file_type"));res.setHeader("Content-Disposition","inline; filename=\""+rs.getString("original_name").replace("\"","")+"\"");try(InputStream in=new FileInputStream(f);OutputStream out=res.getOutputStream()){byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1)out.write(b,0,n);}}catch(Exception e){res.sendError(500,e.getMessage());}} }
